<template>
 <view class="transfer-page">
  <view class="green-top"><NativeStatusSpacer/><view class="navigation"><button class="back" aria-label="返回" @tap="back">‹</button><text>转学申请</text></view></view>
  <view class="paper">
   <view v-if="loading" class="state">正在加载</view><view v-if="error" class="error" role="alert">{{error}}</view>
   <template v-if="options&&!application">
    <view class="child-summary"><image src="/static/pixel/default-child-avatar.png" mode="aspectFill"/><view class="child-copy"><text class="child-name">{{options.studentName}}</text><picker :range="institutionLabels" :value="sourceIndex" :disabled="busy||choosing" @change="changeSource"><view class="current-class">当前班级：{{source?.classNames.join('、')||'暂无班级信息'}}<text v-if="options.institutions.length>1">⌄</text></view></picker><text class="institution">{{source?.name||'暂无有效入学机构'}}</text></view></view>
    <view v-if="source" class="form">
     <picker :range="transferTargets" :value="targetIndex" :disabled="busy||choosing" @change="targetIndex=Number($event.detail.value)"><view class="inline-field"><text>转学类型<text class="required">*</text></text><view class="field-value"><text>{{transferTargets[targetIndex]||'请选择'}}</text><text class="arrow">›</text></view></view></picker>
     <view class="reason-field"><text class="field-label">转学原因<text class="required">*</text></text><view class="textarea-shell"><textarea v-model="reason" :disabled="busy||choosing" maxlength="400" placeholder="请填写转学原因"/><text class="counter">{{Array.from(reason).length}}/200</text></view></view>
     <view class="inline-field date-field"><text>预计转学日期<text class="required">*</text></text><picker mode="date" :value="effectiveDate" :start="today" :disabled="busy||choosing" @change="effectiveDate=$event.detail.value"><view class="date-value"><PrototypeIcon name="calendar" :size="30"/><text>{{effectiveDate}}</text><text class="arrow">›</text></view></picker></view>
     <view class="materials"><text class="field-label">相关证明材料</text><view v-for="proof in proofs" :key="proof.id" class="proof-row"><view class="proof-icon"><view/></view><view class="proof-copy"><text>{{proof.originalName}}</text><text class="proof-size">{{sizeText(proof.sizeBytes)}}</text></view><button :disabled="busy||choosing" :aria-label="'移除'+proof.originalName" class="remove" @tap="removeProof(proof)">×</button></view><button v-if="proofs.length<3" class="add-proof" :disabled="busy||choosing" @tap="chooseProofs"><text class="plus">＋</text><text>{{uploading?'正在上传材料':'添加材料（最多3个）'}}</text></button></view>
     <button class="submit" :disabled="busy||choosing||uncertain" :loading="submitting" @tap="submit">{{submitting?'正在提交':'提交转学申请'}}</button>
    </view>
   </template>
   <view v-if="application" class="result"><view class="result-symbol"><PrototypeIcon name="check" :size="60"/></view><text class="result-title">申请已提交</text><text class="result-copy">等待当前入学机构审核</text><button class="submit" @tap="back">返回列表</button></view>
   <button v-if="uncertain||application" class="return" @tap="openRecords">查看申请记录</button>
  </view>
 </view>
</template>
<script setup lang="ts">
import {computed,ref} from 'vue';
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';
import PrototypeIcon from '@/components/PrototypeIcon.vue';
import {getOrganizationSession} from '@/session/organization-session';
import {getParentSession} from '@/session/parent-session';
import {parentChildrenApi} from '@/api/parent-children';
import {transferApplicationApi,uploadTransferProof,uploadInstitutionTransferProof,type TransferOptions,type TransferProof,type TransferProposal,type TransferContext} from '@/api/transfer-application';
import {buildTransferSubmission,transferTargets} from '@/models/transfer-proposal-draft';
const options=ref<TransferOptions|null>(null),proofs=ref<TransferProof[]>([]),application=ref<TransferProposal|null>(null);
const sourceIndex=ref(0),targetIndex=ref(0),reason=ref(''),loading=ref(false),uploading=ref(false),submitting=ref(false),removing=ref(false),choosing=ref(false),uncertain=ref(false),error=ref('');
const busy=computed(()=>loading.value||uploading.value||submitting.value||removing.value),source=computed(()=>options.value?.institutions[sourceIndex.value]),institutionLabels=computed(()=>options.value?.institutions.map(i=>`${i.name} · ${i.classNames.join('、')||'暂无班级信息'}`)||[]);
function localDate(){const date=new Date();return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
const today=localDate(),effectiveDate=ref(today);let institutionMode=false,sourceId='',studentId='',familyId='',token='',revision=0,visible=false;
function selection(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function activeSession(){return institutionMode?getOrganizationSession():getParentSession();}
function sameScope(){const selected=selection();return !!token&&activeSession()?.accessToken===token&&selected?.accessToken===token&&selected.organizationId===familyId&&(institutionMode?['SCHOOL','TRAINING_INSTITUTION'].includes(selected.typeCode||''):selected.typeCode==='FAMILY');}
function current(n:number){return visible&&n===revision&&sameScope();}
function context():TransferContext{if(!sameScope()||!source.value)throw new Error('组织或入学关系已变化，请返回重新进入');return {accessToken:token,studentId,familyOrganizationId:familyId,sourceInstitutionId:source.value.id};}
onLoad(query=>{institutionMode=query?.mode==='INSTITUTION';sourceId=typeof query?.sourceId==='string'?query.sourceId:'';studentId=typeof query?.studentId==='string'?query.studentId:'';familyId=institutionMode?sourceId:typeof query?.familyId==='string'?query.familyId:'';});
onShow(()=>{visible=true;if(choosing.value)return;void load();});
function hide(){visible=false;if(choosing.value)return;if(submitting.value)uncertain.value=true;++revision;loading.value=false;uploading.value=false;removing.value=false;submitting.value=false;}
onHide(hide);onUnload(hide);
async function load(){const n=++revision;const nextToken=activeSession()?.accessToken||'';if(token&&token!==nextToken){options.value=null;proofs.value=[];application.value=null;reason.value='';uncertain.value=false;sourceIndex.value=0;}token=nextToken;loading.value=true;error.value='';let scopeChecked=false;try{
 if(!/^[1-9]\d*$/.test(studentId)||!/^[1-9]\d*$/.test(familyId)||!sameScope())throw new Error('请从当前组织的孩子档案进入');scopeChecked=true;
 const me=await parentChildrenApi.me(token);if(!current(n))return;if(!me.permissionCodes.includes('STUDENT_TRANSFER_REQUEST_CREATE')||(institutionMode&&!me.permissionCodes.includes('STUDENT_ORGANIZATION_MANAGE')))throw new Error('当前账号没有转学申请权限');
 const result=await (institutionMode?transferApplicationApi.institutionOptions(token,studentId,sourceId):transferApplicationApi.options(token,studentId,familyId));if(!current(n))return;options.value=result;if(sourceIndex.value>=result.institutions.length)sourceIndex.value=0;
 if(uncertain.value)error.value='提交结果尚待确认，请返回核对申请记录后再操作';
 }catch(e){if((!scopeChecked&&visible&&n===revision)||current(n)){options.value=null;error.value=e instanceof Error?e.message:'加载未完成';}}finally{if(n===revision)loading.value=false;}}
function changeSource(event:{detail:{value:string}}){if(!busy.value&&!choosing.value)sourceIndex.value=Number(event.detail.value);}
function sizeText(size:number){return size>=1048576?`${(size/1048576).toFixed(1)}MB`:`${Math.max(1,Math.ceil(size/1024))}KB`;}
function pickFiles(count:number):Promise<{path:string;size:number}[]>{return new Promise((resolve,reject)=>{
 // #ifdef MP-WEIXIN
 uni.chooseMessageFile({count,type:'file',extension:['pdf','jpg','jpeg','png'],success:r=>resolve(r.tempFiles.map(f=>({path:f.path,size:f.size}))),fail:reject});
 // #endif
 // #ifndef MP-WEIXIN
 uni.chooseFile({count,type:'all',extension:['.pdf','.jpg','.jpeg','.png'],success:r=>{const paths=Array.isArray(r.tempFilePaths)?r.tempFilePaths:[r.tempFilePaths];const files=Array.isArray(r.tempFiles)?r.tempFiles:[r.tempFiles];resolve(files.map((f,i)=>({path:('path' in f?f.path:undefined)||paths[i],size:f.size})));},fail:reject});
 // #endif
 });}
async function chooseProofs(){if(busy.value||choosing.value||proofs.value.length>=3)return;let captured:TransferContext;try{captured=context();}catch(e){error.value=(e as Error).message;return;}const n=revision;choosing.value=true;error.value='';try{const files=await pickFiles(3-proofs.value.length);choosing.value=false;if(!current(n))return;uploading.value=true;for(const file of files){if(!current(n))return;if(file.size<=0||file.size>10485760)throw new Error('每份材料须在10MB以内');const proof=await (institutionMode?uploadInstitutionTransferProof(captured,file.path):uploadTransferProof(captured,file.path));if(!current(n))return;proofs.value.push(proof);}}catch(e){const message=e instanceof Error?e.message:String((e as {errMsg?:string})?.errMsg||'材料选择未完成');if(current(n)&&!/cancel/i.test(message))error.value=message;}finally{choosing.value=false;if(n===revision)uploading.value=false;}}
async function removeProof(proof:TransferProof){if(busy.value||choosing.value)return;const n=revision;removing.value=true;error.value='';try{const c=context();await transferApplicationApi.retire(c.accessToken,c.familyOrganizationId,proof.id);if(current(n))proofs.value=proofs.value.filter(p=>p.id!==proof.id);}catch(e){if(current(n))error.value=e instanceof Error?e.message:'材料未能移除';}finally{if(n===revision)removing.value=false;}}
async function submit(){if(busy.value||choosing.value||uncertain.value)return;const n=revision;error.value='';try{const c=context(),data=buildTransferSubmission({targetIndex:targetIndex.value,reason:reason.value,effectiveDate:effectiveDate.value,attachmentIds:proofs.value.map(p=>p.id)},localDate());submitting.value=true;const result=await (institutionMode?transferApplicationApi.submitInstitution(c,data):transferApplicationApi.submit(c,data));if(current(n)){application.value=result;proofs.value=[];reason.value='';}}catch(e){if(current(n))error.value=e instanceof Error?e.message:'申请未能提交';}finally{if(n===revision)submitting.value=false;}}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:institutionMode?'/pages/organization-home/organization-home':'/pages/parent-children/parent-children'})});}
function openRecords(){if(sameScope())uni.navigateTo({url:'/pages/transfer-records/transfer-records'});}
</script>
<style scoped>
.transfer-page{min-height:100vh;display:flex;flex-direction:column;background:#fff;color:#1c2c35;}.green-top{background:linear-gradient(110deg,#155c48,#176149 60%,#256f50);}.navigation{height:94rpx;position:relative;display:flex;align-items:center;justify-content:center;color:#fff;font-size:32rpx;font-weight:650;}.navigation .back{position:absolute;left:20rpx;top:0;height:94rpx;line-height:84rpx;width:54rpx;padding:0;background:transparent;border:0;color:#fff;font-size:64rpx;font-weight:300;}.back::after,.remove::after,.add-proof::after,.submit::after,.return::after{border:0;}.paper{position:relative;margin-top:-2rpx;padding:34rpx 38rpx 50rpx;background:linear-gradient(#fff,#fcfdfb);border-radius:34rpx 34rpx 0 0;min-height:0;flex:1;box-sizing:border-box;}.child-summary{display:flex;align-items:center;gap:22rpx;padding:0 2rpx 30rpx;border-bottom:1rpx solid #e5ece8;}.child-summary image{width:116rpx;height:116rpx;border-radius:50%;flex-shrink:0;}.child-copy{min-width:0;display:flex;flex-direction:column;gap:8rpx;}.child-name{font-size:32rpx;font-weight:700;}.current-class,.institution{font-size:25rpx;color:#74838c;line-height:1.5;}.current-class{display:flex;gap:12rpx;}.institution{font-size:24rpx;}.inline-field{display:flex;align-items:center;justify-content:space-between;gap:20rpx;min-height:90rpx;border-bottom:1rpx solid #e7ece8;font-size:29rpx;}.required{color:#e85f55;margin-left:8rpx;}.field-value{display:flex;align-items:center;gap:20rpx;}.arrow{font-size:42rpx;font-weight:300;color:#81949a;}.field-label{display:block;font-size:29rpx;margin:22rpx 0 12rpx;}.textarea-shell{position:relative;border:1rpx solid #e5eae7;border-radius:18rpx;background:#f7f9f8;padding:18rpx 18rpx 34rpx;}.textarea-shell textarea{width:100%;height:120rpx;line-height:1.6;font-size:28rpx;color:#34424e;}.counter{position:absolute;right:16rpx;bottom:12rpx;color:#95a1a8;font-size:23rpx;}.date-field{margin-top:18rpx;}.date-value{display:flex;align-items:center;gap:16rpx;padding:9rpx 16rpx;border:1rpx solid #e2e8e4;border-radius:16rpx;color:#5a6e7b;font-size:27rpx;}.materials .field-label{margin-top:26rpx;}.proof-row{display:flex;align-items:center;gap:18rpx;background:#f1f5f4;border-radius:15rpx;padding:16rpx 18rpx;margin-bottom:12rpx;}.proof-icon{width:38rpx;height:44rpx;background:#4b797b;border-radius:4rpx;position:relative;flex-shrink:0;}.proof-icon::after{content:'';position:absolute;right:0;top:0;border-top:11rpx solid #f1f5f4;border-left:11rpx solid #a1bcba;}.proof-icon view{position:absolute;width:19rpx;left:8rpx;top:20rpx;border-top:2rpx solid #fff;border-bottom:2rpx solid #fff;height:7rpx;}.proof-copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:5rpx;font-size:27rpx;}.proof-copy>text:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}.proof-size{color:#8897a1;font-size:23rpx;}.remove{font-size:39rpx;padding:0;background:transparent;color:#83969f;line-height:48rpx;width:44rpx;height:48rpx;margin:0;}.add-proof{width:100%;display:flex;align-items:center;justify-content:center;gap:12rpx;height:78rpx;line-height:78rpx;background:#f0f4f2;color:#7b8b94;border-radius:15rpx;font-size:28rpx;font-weight:500;}.plus{font-size:37rpx;font-weight:300;}.submit{margin-top:28rpx;height:100rpx;line-height:100rpx;width:100%;border-radius:27rpx;color:#fff;background:linear-gradient(110deg,#116448,#0c6544);font-size:31rpx;font-weight:650;box-shadow:0 8rpx 15rpx #165e4715;}.submit[disabled]{background:#9db6ac;color:#fff;}.state,.error{padding:22rpx 0;font-size:27rpx;line-height:1.5;}.error{color:#b94d44;}.result{text-align:center;padding:80rpx 0;}.result-symbol{margin:0 auto 24rpx;width:108rpx;height:108rpx;display:flex;align-items:center;justify-content:center;background:#e8f3e9;border-radius:50%;}.result-title,.result-copy{display:block;}.result-title{font-size:36rpx;font-weight:650;}.result-copy{margin-top:20rpx;color:#7e8e87;font-size:28rpx;}.return{margin-top:25rpx;color:#185943;background:#eaf2ec;font-size:28rpx;border-radius:18rpx;}
</style>
<style scoped>.child-copy{flex:1;overflow:hidden}.child-name,.institution{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.current-class{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}.child-copy picker{min-width:0;width:100%}</style>
